function PLAN({ values, previous }) {
  if (!Array.isArray(values) || !Array.isArray(values[0])) throw Error("Sheet needs headers");
  const headers = values[0];
  const column = (name) => {
    const matches = headers.flatMap((v, i) => (v === name ? [i] : []));
    if (matches.length !== 1) throw Error("Missing or duplicate " + name + " header");
    return matches[0];
  };
  const emailColumn = column("Email"),
    statusColumn = column("Status");
  const rows = values.slice(1).map((row, i) => {
    if (!Array.isArray(row)) throw Error("Invalid row");
    return {
      row: i + 2,
      email: String(row[emailColumn] ?? "").trim(),
      status: String(row[statusColumn] ?? ""),
      cells: row,
    };
  });
  const snapshot = rows.map((r) => r.cells);
  if (previous == null) return { snapshot, items: [] };
  if (!Array.isArray(previous)) throw Error("Invalid previous snapshot");
  const seen = new Set(),
    items = [];
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    if (
      JSON.stringify(r.cells) === JSON.stringify(previous[i]) ||
      r.status.trim() ||
      !r.email ||
      seen.has(r.email)
    )
      continue;
    seen.add(r.email);
    items.push({ row: r.row, email: r.email });
  }
  return { snapshot, items };
}

export default async function inspect({ values }, context) {
  const previous = await context.state.get("sheet-snapshot");
  const result = PLAN({ values, previous });
  return { items: result.items, snapshot: result.snapshot };
}

