export default function next({ items, previousState }) {
  if (!Array.isArray(items)) throw Error("Invalid items");
  const index = previousState?.index ?? 0;
  if (!Number.isInteger(index) || index < 0 || index > items.length)
    throw Error("Invalid item index");
  const current = items[index];
  return {
    state: { index: index + 1 },
    more: index < items.length,
    current: current ?? {},
    email: current?.email ?? "unused@example.invalid",
  };
}

